static RAMFN uint32_t fl_status_ram(void)                /* SR1 | SR2 << 8 */
{
    fl_saved_t s; uint32_t v;
    if (fl_enter(&s)) return 0xFFFFFFFFu;
    v = fl_rdsr(0x05) | ((uint32_t)fl_rdsr(0x35) << 8);
    fl_exit(&s);
    return v;
}

void sm_poll(uint32_t now, sm_send_fn send)
{
    if (sm_hello) {
        sm_heard = now;
        if (!sm_live || sm_hello > 1) sm_full = 1;
        sm_hello = 0;
        sm_live = 1;
    }
    if (now - sm_heard >= SM_TIMEOUT) sm_live = 0;
    while (sm_live && sm_sent < sm_length) {
        int r = send(sm_buffer + sm_sent + 1, sm_buffer[sm_sent]);
        if (r == -2) break; /* busy: the rest next time */
        if (r) sm_live = 0;
        sm_sent += 1u + sm_buffer[sm_sent];
    }
    if (!sm_live || sm_sent >= sm_length) {
        sm_length = sm_sent = 0;
    } else if (sm_sent) {
        /* Move what's left to the front, so the room it freed takes new rows now (with a small buffer, waiting for
         * all of it to go first held the screen up too long). Forward copy: the data only moves down. */
        unsigned i, n = sm_length - sm_sent;
        for (i = 0; i < n; i++)
            sm_buffer[i] = sm_buffer[sm_sent + i];
        sm_length = n;
        sm_sent = 0;
    }
}

/* paint the list far to near; the reflection fades down from the floor line */
static void paint(float presence, int reflection)
{
    int i, j;
    for (i = 1; i < nitems; i++) {             /* sort by depth, far first (insertion: the list is small) */
        item_t t = items[i];
        for (j = i - 1; j >= 0 && items[j].depth < t.depth; j--)
            items[j + 1] = items[j];
        items[j + 1] = t;
    }
    for (i = 0; i < nitems; i++) {
        const item_t *it = &items[i];
        const float *p = &b_pts[2 * it->p0];
        float minx = 1e9f, maxx = -1e9f, miny = 1e9f, maxy = -1e9f, a = it->alpha * presence;
        int k, x, y;
        for (k = 0; k < it->n; k++) {
            minx = p[2 * k] < minx ? p[2 * k] : minx;
            maxx = p[2 * k] > maxx ? p[2 * k] : maxx;
            miny = p[2 * k + 1] < miny ? p[2 * k + 1] : miny;
            maxy = p[2 * k + 1] > maxy ? p[2 * k + 1] : maxy;
        }
        mask_clear((int)minx - 3, (int)miny - 3, (int)maxx + 4, (int)maxy + 4);
        if (it->outline)
            mask_line(p, it->n, 1.0f);
        else
            mask_poly(p, it->n);
        if (!reflection) {
            mask_fill(it->col, a);
            continue;
        }
        for (y = mbox.y0; y < mbox.y1; y++) {  /* the floor's mirror: 34 %, fading over 40 px */
            float f = 1 - (y - b_cy) / 40.0f, aa;
            if (y <= b_cy || f <= 0)
                continue;
            aa = a * 0.34f * f * f;
            for (x = mbox.x0; x < mbox.x1; x++) {
                int m = MASK[y * SW + x];
                if (m)
                    blend(x, y, it->col, (int)(m * aa * 256 / 255));
            }
        }
    }
}

/* the fine gold rim line; with a glint (0..1 along it) a bright travelling spot with a four-ray star */
static void gold_polyline(const float *pts, int n, float alpha, float glint)
{
    float seg[NPLAN], tot = 0, acc = 0;
    int i;
    for (i = 0; i + 1 < n; i++) {
        float dx = pts[2 * i + 2] - pts[2 * i], dy = pts[2 * i + 3] - pts[2 * i + 1];
        seg[i] = esqrt(dx * dx + dy * dy);
        tot += seg[i];
    }
    if (tot <= 0)
        return;
    for (i = 0; i + 1 < n; i++) {
        float mid = (acc + seg[i] / 2) / tot, a = alpha * (0.35f + 0.65f * (mid * 3 < 1 ? mid * 3 : 1));
        rgb_t col = GOLD;
        acc += seg[i];
        if (glint >= 0) {
            float u = (mid - glint) / 0.07f, g = fexp2(-1.442695f * u * u);
            a = a + g > 1 ? 1 : a + g;
            col = mixc(GOLD, GOLD_HI, g);
        }
        mask_clear((int)(pts[2 * i] < pts[2 * i + 2] ? pts[2 * i] : pts[2 * i + 2]) - 2,
                   (int)(pts[2 * i + 1] < pts[2 * i + 3] ? pts[2 * i + 1] : pts[2 * i + 3]) - 2,
                   (int)(pts[2 * i] > pts[2 * i + 2] ? pts[2 * i] : pts[2 * i + 2]) + 3,
                   (int)(pts[2 * i + 1] > pts[2 * i + 3] ? pts[2 * i + 1] : pts[2 * i + 3]) + 3);
        mask_line(&pts[2 * i], 2, 1.0f);
        mask_fill(col, a);
    }
    if (glint >= 0 && glint <= 1) {
        float gx, gy, t;
        int r;
        acc = 0;
        i = 0;
        while (i < n - 2 && acc + seg[i] < glint * tot)
            acc += seg[i++];
        t = (glint * tot - acc) / (seg[i] > 1e-6f ? seg[i] : 1e-6f);
        gx = pts[2 * i] + (pts[2 * i + 2] - pts[2 * i]) * t;
        gy = pts[2 * i + 1] + (pts[2 * i + 3] - pts[2 * i + 1]) * t;
        glow(gx, gy, 3.0f, GOLD_HI, 0.9f);
        glow(gx, gy, 9.0f, GOLD, 0.18f);
        for (r = 1; r < 13; r++) {
            float k = (1 - r / 13.0f) * (1 - r / 13.0f);
            int ix = (int)(gx + 0.5f), iy = (int)(gy + 0.5f);
            addc(ix + r, iy, GOLD_HI, AF(0.9f * k));
            addc(ix - r, iy, GOLD_HI, AF(0.9f * k));
            if (r < 7) {
                addc(ix, iy + r, GOLD_HI, AF(0.7f * k));
                addc(ix, iy - r, GOLD_HI, AF(0.7f * k));
            }
        }
    }
}

/* anchor 'l', 'c' or 'r'; into the frame (alpha blended) or, mask = 1, into the mask (for its glow) */
static float text_at(float x, float y, const erk_font *f, const char *s, rgb_t c, float track, char anchor, float alpha,
                     int mask)
{
    float w = twidth(f, s, track), pen;
    int a = AF(alpha);
    if (anchor == 'c')
        x -= w / 2;
    else if (anchor == 'r')
        x -= w;
    pen = (float)(int)(x + 0.5f);
    for (; *s; s++) {
        const erk_glyph *g = glyph_of(f, (uint8_t)*s);
        int gx, gy, i, j;
        if (!g) {
            pen += f->px * 0.3f + track;
            continue;
        }
        gx = (int)(pen + 0.5f) + g->xo;
        gy = (int)y + g->yo;
        for (j = 0; j < g->h; j++)
            for (i = 0; i < g->w; i++) {
                uint32_t k = (uint32_t)j * g->w + (uint32_t)i;
                uint32_t v = (f->d[g->off + (k >> 1)] >> ((k & 1u) ? 0 : 4)) & 15u;
                if (!v)
                    continue;
                if (mask) {
                    int xx = gx + i, yy = gy + j;
                    if ((unsigned)xx < SW && (unsigned)yy < SH && MASK[yy * SW + xx] < v * 17u)
                        MASK[yy * SW + xx] = (uint8_t)(v * 17u);
                } else {
                    blend(gx + i, gy + j, c, (int)(v * (uint32_t)a / 15u));
                }
            }
        pen += g->adv / 16.0f + track;
    }
    return w;
}

/* the gold rule: fades at both ends; with the ornament a small lozenge in a gap at the centre */
static void hairline(float x0, float x1, int y, rgb_t c, float alpha, int ornament)
{
    float cx = (x0 + x1) / 2;
    if (ornament) {
        hline(x0, cx - 7, y, c, alpha, (cx - x0) * 0.7f);
        hline(cx + 7, x1, y, c, alpha, (x1 - cx) * 0.7f);
        lozenge(cx - 0.5f, (float)y, 2.5f, c, alpha, 0);
    } else {
        hline(x0, x1, y, c, alpha, (x1 - x0) * 0.3f);
    }
}

void fm1_alnk0_irq(void)                            /* via isr_alnk0 (hal/fm1_isr.S) */
{
    uint8_t p = fm1_audio_pending();
    fm1_audio_ack_aux(p);
    if (p & FM1_AUDIO_HALF) {
        uint32_t half = fm1_audio_free_half();
        render_block(&abuf[half * HALF_WORDS]);
        fm1_audio_ack_half();
        if (fm1_audio_free_half() != half) {
            fm1b_dbg.late++;                         /* the DMA moved on while we rendered */
            audio_xruns++;
        }
    }
}

static void enter_uboot(const char *why)
{
    fm1_audio_stop();
    lcd_fill(0, 0, 240, 240, C_BLACK);
    draw_text_box(0, 110, 240, &FONT_S, why, C_WHITE, 1);
    fm1_delay_ms(20);
    usb_detach();
    fm1_delay_ms(30);
    bootguard.pending = 0;                          /* intentional reset: not a failed boot */
    radio_clean_exit();
    fm1_enter_uboot();
}

void erk_sustain(int val)
{
    int i, on;
    sus_lvl = clampi(val, 0, 127) * 258;
    on = sus ? sus_lvl > SUS_OFF : sus_lvl > SUS_ON;
    send_t = sus_lvl;
    /* half pedal: between half and full the held notes lose more the less the pedal is down */
    {
        int32_t f = clampi((sus_lvl - SUS_ON) * 32767 / (32767 - SUS_ON), 0, 32767);   /* 0 at the bite, 1 full */
        m_half = mulq30(1u << 30, 1u << 30) - (uint32_t)muls((int32_t)((1u << 30) - (bk ? bk->key[40].mr2 : (1u << 30))),
                                                             32767 - f, 15) / 3u;
    }
    if (sus && !on) {
        for (i = 0; i < ERK_VOICES + ERK_DYING; i++)
            if (vc[i].state == V_SUST && !(vc[i].flags & F_SOST))
                release(&vc[i]);
        pad_let_go(0);
    }
    sus = on;
    erk_sus_q15 = sus_lvl;
}

void erk_sostenuto(int on)
{
    int i;
    on = !!on;
    if (on && !sost) {                                /* the dampers of the notes sounding now stay up */
        uint32_t m[3] = {0, 0, 0};
        for (i = 0; i < ERK_VOICES + ERK_DYING; i++)
            if (vc[i].state == V_ON || (vc[i].state == V_SUST && sus)) {
                vc[i].flags |= F_SOST;
                m[vc[i].key >> 5] |= 1u << (vc[i].key & 31);
            }
        erk_sost_keys[0] = m[0];
        erk_sost_keys[1] = m[1];
        erk_sost_keys[2] = m[2];
    } else if (!on && sost) {
        erk_sost_keys[0] = erk_sost_keys[1] = erk_sost_keys[2] = 0;
        for (i = 0; i < ERK_VOICES + ERK_DYING; i++)
            if (vc[i].flags & F_SOST) {
                vc[i].flags &= (uint8_t)~F_SOST;
                if (vc[i].state == V_SUST && !sus)
                    release(&vc[i]);
            }
        if (!sus)
            pad_let_go(0);
    }
    sost = on;
}

void erk_shed(void)
{
    int i, n = 0;
    voice *q = 0;
    for (i = 0; i < ERK_VOICES + ERK_DYING && n < 2; i++)
        if (vc[i].state == V_REL || vc[i].state == V_RING || (vc[i].state == V_SUST && gain_of(&vc[i]) < 600)) {
            vc[i].state = V_FADE;
            vc[i].m = FADE_M;
            n++;
        }
    if (n)
        return;
    for (i = 0; i < ERK_VOICES + ERK_DYING; i++)  /* none let go (every note held): the quietest held one, if faint */
        if ((vc[i].state == V_ON || vc[i].state == V_SUST) && gain_of(&vc[i]) < 2000 &&
            (!q || gain_of(&vc[i]) < gain_of(q)))
            q = &vc[i];
    if (q) {
        q->state = V_FADE;
        q->m = FADE_M;
    }
}
